<template><div class="scan-page"><el-card v-loading="loading" class="scan-card"><template #header><div class="title">万悦城铺位服务</div></template><el-result v-if="error" icon="error" title="二维码无法识别" :sub-title="error"/><template v-else-if="stall"><el-descriptions :column="1" border><el-descriptions-item label="铺位">{{stall.floorName||''}} {{stall.stallCode}}</el-descriptions-item><el-descriptions-item label="当前商户">{{stall.merchantName||'-'}}</el-descriptions-item><el-descriptions-item label="业态">{{stall.businessType||'-'}}</el-descriptions-item><el-descriptions-item label="铺位状态">{{statusText(stall.stallStatus)}}</el-descriptions-item></el-descriptions><div class="actions"><template v-if="userStore.token"><el-button v-if="canClearance" type="primary" @click="openClearance">提交商户日清</el-button><el-button @click="coming('设备维修预约')">设备维修预约</el-button><el-button v-if="canReview" type="warning" @click="openProperty">物业清场检查</el-button></template><el-button v-else type="primary" @click="login">登录后办理</el-button></div><el-alert title="二维码永久对应当前铺位，商户变更后无需重新张贴。" type="info" :closable="false" show-icon/></template></el-card>
<el-dialog v-model="clearanceVisible" title="商户三关一闭日清" width="520px"><el-alert v-if="periodMessage" :title="periodMessage" :type="periodOpen?'info':'warning'" :closable="false"/><dynamic-form v-if="periodOpen" :fields="clearanceFields" v-model="clearanceAnswers"/><template #footer><el-button @click="clearanceVisible=false">取消</el-button><el-button v-if="periodOpen" type="primary" :loading="saving" @click="submitClearance">提交</el-button></template></el-dialog>
<el-dialog v-model="propertyVisible" title="物业清场检查" width="520px"><el-alert v-if="propertyTemplate.name" :title="`${propertyTemplate.name}（第${propertyTemplate.versionNo}版）`" type="info" :closable="false"/><dynamic-form :fields="propertyFields" v-model="propertyAnswers"/><template #footer><el-button @click="propertyVisible=false">取消</el-button><el-button type="primary" :loading="propertySaving" @click="submitProperty">提交检查</el-button></template></el-dialog>
</div></template>
<script setup lang="ts">
import{computed,defineComponent,h,onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElButton,ElForm,ElFormItem,ElInput,ElInputNumber,ElMessage,ElSwitch}from'element-plus';import{operationMerchantApi,operationClearanceApi,operationTemplateApi,operationPropertyApi}from'@/api/operation';import{useUserStore}from'@/stores/user'
const DynamicForm=defineComponent({props:{fields:{type:Array,default:()=>[]},modelValue:{type:Object,required:true}},emits:['update:modelValue'],setup(p,{emit}){const set=(k:string,v:any)=>emit('update:modelValue',{...(p.modelValue as any),[k]:v});return()=>h(ElForm,{labelWidth:'160px'},()=> (p.fields as any[]).map(f=>h(ElFormItem,{label:f.label,required:f.required},()=>f.type==='BOOLEAN'?h(ElSwitch,{modelValue:(p.modelValue as any)[f.code],activeText:'正常',inactiveText:'异常','onUpdate:modelValue':(v:any)=>set(f.code,v)}):f.type==='NUMBER'?h(ElInputNumber,{modelValue:(p.modelValue as any)[f.code],'onUpdate:modelValue':(v:any)=>set(f.code,v)}):h(ElInput,{modelValue:(p.modelValue as any)[f.code],type:f.code==='exceptionDescription'?'textarea':'text','onUpdate:modelValue':(v:any)=>set(f.code,v)}))) )}})
const route=useRoute(),router=useRouter(),userStore=useUserStore(),stall=ref<any>(null),loading=ref(true),error=ref('');const canClearance=computed(()=>userStore.hasPermission('operation.clearance.submit')),canReview=computed(()=>userStore.hasPermission('operation.clearance.review'));const clearanceVisible=ref(false),propertyVisible=ref(false),periodOpen=ref(false),periodMessage=ref(''),saving=ref(false),propertySaving=ref(false),clearanceFields=ref<any[]>([]),propertyFields=ref<any[]>([]),clearanceAnswers=ref<any>({}),propertyAnswers=ref<any>({}),propertyTemplate=ref<any>({});const token=()=>String(route.params.token);const statusText=(v:string)=>({OCCUPIED:'在用',AVAILABLE:'空置',RENOVATING:'装修中'}as any)[v]||v||'-';const defaults=(fs:any[])=>Object.fromEntries(fs.map(f=>[f.code,f.type==='BOOLEAN'?(f.expected??true):'']));function login(){router.push({path:'/login',query:{redirect:route.fullPath}})}function coming(n:string){ElMessage.info(`${n}将在后续阶段接入`)}
async function openClearance(){const[p,t]:any[]=await Promise.all([operationClearanceApi.period(),operationTemplateApi.stall(token())]);periodOpen.value=!!p.open;periodMessage.value=p.open?`日清日期：${p.periodDate}；模板：${t.name}（第${t.versionNo}版）`:p.message;clearanceFields.value=t.fields||[];clearanceAnswers.value=defaults(clearanceFields.value);clearanceVisible.value=true}async function submitClearance(){saving.value=true;try{const r:any=await operationClearanceApi.submit(token(),{answers:clearanceAnswers.value});ElMessage.success(r.status==='NORMAL'?'日清提交成功':'异常日清已提交');clearanceVisible.value=false}finally{saving.value=false}}
async function openProperty(){const t:any=await operationPropertyApi.template(token());propertyTemplate.value=t;propertyFields.value=t.fields||[];propertyAnswers.value=defaults(propertyFields.value);propertyVisible.value=true}async function submitProperty(){propertySaving.value=true;try{const r:any=await operationPropertyApi.submit(token(),propertyAnswers.value);ElMessage.success(r.status==='NORMAL'?'物业检查正常':'物业检查异常已登记');propertyVisible.value=false}finally{propertySaving.value=false}}
onMounted(async()=>{try{stall.value=await operationMerchantApi.publicStall(token())}catch(e:any){error.value=e?.message||'二维码无效'}finally{loading.value=false}})
</script><style scoped>.scan-page{min-height:100vh;background:#f3f6fa;padding:24px 12px}.scan-card{max-width:560px;margin:auto}.title{text-align:center;font-size:22px;font-weight:700}.actions{display:flex;flex-wrap:wrap;gap:12px;margin:22px 0}.actions .el-button{flex:1;margin:0}@media(max-width:480px){.scan-page{padding:0}.scan-card{min-height:100vh;border:0}.actions .el-button{flex-basis:100%}}</style>
